window.OVA_CONTENT={"slug":"seccion-03-herramientas-de-biologia-molecular","title":"Herramientas de biología molecular","minutes":40,"summary":"Comprende muestreo, extracción, amplificación y comparación molecular para identificar organismos y materiales.","objective":"Explicar qué evidencia puede aportar una herramienta molecular y qué controles necesita.","stages":[{"eyebrow":"Flujo analítico","title":"1. De la muestra al resultado","reading":"El análisis molecular comienza con una pregunta y un plan de muestreo. Después se extrae material, se aplica una técnica, se compara con controles y se interpreta el resultado.","application":"Un resultado técnicamente correcto puede ser poco útil si la muestra no representa el lote.","activity":{"type":"order","question":"Ordena el flujo.","items":["Definir pregunta","Diseñar muestreo","Extraer material genético","Analizar con controles","Interpretar y documentar"],"answer":[0,1,2,3,4],"success":"La calidad se construye desde la pregunta."}},{"eyebrow":"Identidad","title":"2. Qué puede demostrar una secuencia","reading":"Un fragmento de ADN puede compararse con referencias para apoyar la identificación o diferenciación de organismos. La fuerza de la conclusión depende de la región, la calidad y la base de referencia.","application":"Similitud no siempre equivale a identidad completa ni demuestra por sí sola origen geográfico o desempeño.","activity":{"type":"choice","question":"¿Cuál afirmación es prudente?","options":["La comparación apoya una identificación dentro de sus límites","Toda coincidencia revela todas las propiedades","Una secuencia elimina la necesidad de controles"],"answer":[0],"success":"La evidencia molecular responde preguntas delimitadas."}},{"eyebrow":"Controles","title":"3. Evitar conclusiones falsas","reading":"Los controles positivos muestran que el método puede detectar el objetivo; los negativos ayudan a revelar contaminación; las réplicas permiten evaluar consistencia.","application":"Sin controles, una señal o su ausencia resulta difícil de interpretar.","activity":{"type":"match","question":"Relaciona control y función.","pairs":[{"label":"Positivo","value":"deteccion","option":"Verificar capacidad de detección"},{"label":"Negativo","value":"contaminacion","option":"Vigilar contaminación"},{"label":"Réplica","value":"consistencia","option":"Evaluar consistencia"}],"answer":["deteccion","contaminacion","consistencia"],"success":"Los controles dan significado al resultado."}},{"eyebrow":"Aplicación","title":"4. Trazabilidad y certificación","reading":"La evidencia molecular puede respaldar identidad varietal o de especie, detectar sustituciones y relacionar muestras. Debe integrarse con cadena de custodia, registros y procedimientos.","application":"La trazabilidad es un sistema documental y operativo; una prueba es solo una de sus evidencias.","activity":{"type":"multi","question":"Selecciona componentes necesarios.","options":["Muestreo documentado","Cadena de custodia","Referencia validada","Resultado sin identificación de lote"],"answer":[0,1,2],"success":"La evidencia debe conservar su vínculo con el lote."}},{"eyebrow":"Caso aplicado","title":"5. Proveedores de material vegetal","reading":"Una organización recibe material de varios proveedores y busca verificar uniformidad. Puede definir un plan de muestreo y una comparación molecular, manteniendo registros de proveedor, lote y recepción.","application":"La prueba molecular debe complementar inspección y controles productivos.","activity":{"type":"choice","question":"¿Qué debilita más el análisis?","options":["Muestras sin vínculo con los lotes","Uso de referencias documentadas","Registro de recepción"],"answer":[0],"success":"Sin trazabilidad de muestra no hay trazabilidad del resultado."}}],"number":"03","references":["Cunningham, W. P. et al. (2023). Principios de Ciencias Ambientales. McGraw-Hill.","Smith, T. M. y Smith, R. L. (2007). Ecología. Pearson.","Hardin, J. y Lodolce, J. P. (2024). Becker. El mundo de la célula. Pearson.","Marino Buslje, C. y Parisi, G. (2019). Aprender para predecir: la bioinformática como herramienta de estudio en biología.","Hodson de Jaramillo, E. et al. (2019). La bioeconomía: nuevo marco para el crecimiento sostenible en América Latina."]};